import manifest from "@/lib/citations.generated.json"
import { NOTES, type NoteMeta } from "@/lib/notes"
import type { SourceBadgeProps } from "@/lib/sources"

// Generated by scripts/extract-citations.mjs before dev and build.

export type ManifestCitation = SourceBadgeProps & { claim: string }
export type NoteCitations = NoteMeta & { citations: ManifestCitation[] }

export const NOTE_CITATIONS: NoteCitations[] = NOTES.map((note) => {
  const entry = manifest.find((m) => m.fundSlug === note.fundSlug && m.noteId === note.noteId)
  return { ...note, citations: (entry?.citations ?? []) as ManifestCitation[] }
})

export const ALL_FILE_IDS = [...new Set(NOTE_CITATIONS.flatMap((note) => note.citations.map((c) => c.fileId)))]
